cd /workspace/project && python3 -W error -m compileall -q src tests campaign_cli.py > /dev/null && echo "compile OK"; find . -name __pycache__ -type d -exec rm -rf {} + 2>/dev/null; python3 - <<'PYEOF'
import ast, os, sys
# poor-man's unused import check
for root, dirs, files in os.walk('/workspace/project'):
    dirs[:] = [d for d in dirs if d != '__pycache__']
    for f in files:
        if not f.endswith('.py'): continue
        p = os.path.join(root, f)
        src = open(p).read()
        tree = ast.parse(src)
        imported = {}
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for a in node.names:
                    imported[(a.asname or a.name).split('.')[0]] = node.lineno
            elif isinstance(node, ast.ImportFrom):
                for a in node.names:
                    if a.name == '*': continue
                    imported[a.asname or a.name] = node.lineno
        names = set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Name): names.add(node.id)
            elif isinstance(node, ast.Attribute):
                pass
        # also count attribute bases and strings in __all__
        text_names = set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Attribute):
                n = node
                while isinstance(n, ast.Attribute): n = n.value
                if isinstance(n, ast.Name): text_names.add(n.id)
        allnames = set()
        for node in tree.body:
            if isinstance(node, ast.Assign) and any(getattr(t,'id',None)=='__all__' for t in node.targets):
                allnames = set(ast.literal_eval(node.value))
        unused = [k for k in imported if k not in names and k not in text_names and k not in allnames and k not in src.split('__all__')[-1]]
        if unused: print(p, 'unused imports:', unused)
print('import check done')
PYEOF
